input.command:
cd /workspace && cat > src/money.ts <<'EOF'
export function formatAmount(cents: number): string {
  const sign = cents < 0 ? '-' : '';
  const absolute = Math.abs(cents);
  return sign + Math.floor(absolute / 100) + '.' + String(absolute % 100).padStart(2, '0');
}
EOF
cat > src/invoice.ts <<'EOF'
import { formatAmount } from './money';
export function renderInvoice(id: string, cents: number): string { return id + ': $' + formatAmount(cents); }
EOF
cat > src/report.ts <<'EOF'
import { formatAmount } from './money';
export function renderReport(rows: { id: string; cents: number }[]): string {
  return rows.map(row => row.id + ',' + formatAmount(row.cents)).join('\n');
}
EOF
rm src/invoiceAmount.ts src/reportAmount.ts
cat >> checks/public.cjs <<'EOF'

const { formatAmount } = require('../.build/money');
assert.equal(formatAmount(0), '0.00');
assert.equal(formatAmount(5), '0.05');
assert.equal(formatAmount(123), '1.23');
assert.equal(formatAmount(-1), '-0.01');
assert.equal(formatAmount(-12345), '-123.45');
assert.equal(renderInvoice('n', -250), 'n: $-2.50');
assert.equal(renderReport([{ id: 'z', cents: 100 }, { id: 'y', cents: -100 }]), 'z,1.00\ny,-1.00');
EOF
rm -rf .build; tsc -p tsconfig.json && node checks/public.cjs && echo OK; grep -rn "invoiceAmount\|reportAmount" src

